arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for c in d['channels']:
    if c['name']=='standup': print(c['id'], c['name'])
"

